package vn.edu.webpro.robotlab.controller;
import java.io.IOException;import java.sql.SQLException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import vn.edu.webpro.robotlab.dao.*;import vn.edu.webpro.robotlab.model.LibraryResource;import vn.edu.webpro.robotlab.web.*;
@WebServlet("/api/admin/library-resources/*") public final class AdminLibraryResourceServlet extends HttpServlet{private final LibraryResourceDao resources=new LibraryResourceDao(new DatabaseConnectionFactory(System.getenv()));@Override protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{if(AdminAccess.requireAdmin(q,p)==null)return;try{var d=resources.list(100,0,null);String j=d.stream().map(LibraryResource::toJson).reduce((a,b)->a+","+b).orElse("");ApiResponses.json(p,200,"{\"data\":["+j+"],\"meta\":{\"page\":1,\"limit\":100,\"total\":"+d.size()+"}}");}catch(SQLException e){ApiResponses.error(p,503,"DEPENDENCY_NOT_READY","Cơ sở dữ liệu chưa được cấu hình.");}}@Override protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{write(q,p,null,true);}@Override protected void doDelete(HttpServletRequest q,HttpServletResponse p)throws IOException{if(AdminAccess.requireAdmin(q,p)==null||!AdminAccess.requireCsrf(q,p))return;try{if(!resources.remove(id(q))){ApiResponses.error(p,404,"NOT_FOUND","Không tìm thấy nội dung.");return;}p.setStatus(204);}catch(SQLException e){ApiResponses.error(p,409,"RELATION_CONFLICT","Không thể xóa tài nguyên đang được sử dụng.");}}@Override protected void service(HttpServletRequest q,HttpServletResponse p)throws javax.servlet.ServletException,IOException{if("PATCH".equals(q.getMethod())){write(q,p,id(q),false);return;}super.service(q,p);}private void write(HttpServletRequest q,HttpServletResponse p,String old,boolean add)throws IOException{if(AdminAccess.requireAdmin(q,p)==null||!AdminAccess.requireCsrf(q,p))return;try{String b=q.getReader().lines().reduce("",(a,c)->a+c);LibraryResource x=input(b,add?null:old);LibraryResource saved=add?resources.create(x):resources.update(old,x);if(saved==null){ApiResponses.error(p,404,"NOT_FOUND","Không tìm thấy nội dung.");return;}ApiResponses.json(p,add?201:200,"{\"data\":"+saved.toJson()+"}");}catch(IllegalArgumentException e){ApiResponses.error(p,422,"VALIDATION_ERROR","Dữ liệu tài nguyên không hợp lệ.");}catch(SQLException e){ApiResponses.error(p,409,"CONFLICT","Không thể lưu tài nguyên.");}}private String id(HttpServletRequest q){return q.getPathInfo()==null?"":q.getPathInfo().substring(1);}private LibraryResource input(String b,String old){String id=old==null?Json.stringField(b,"id").trim():old,robot=Json.stringField(b,"robotId").trim(),title=Json.stringField(b,"title").trim(),type=Json.stringField(b,"type").trim(),url=Json.stringField(b,"url").trim(),description=Json.stringField(b,"description").trim();if(!id.matches("[a-z0-9]+(?:-[a-z0-9]+)*")||!java.util.Set.of("image","document","link").contains(type)||title.isEmpty()||url.isEmpty()||description.isEmpty())throw new IllegalArgumentException();return new LibraryResource(id,robot.isEmpty()?null:robot,title,type,url,description);}}
